    // Contrast: darker and more saturated toward the lower inner side, then the dark refracted rim.
    col.rgb *= mix(vec3(1.0), vec3(0.78, 0.92, 0.60), low * smoothstep(0.12, 0.5, tilt) * 0.8);
    col.rgb *= mix(0.92, 1.03, wrapL);
